<?php
declare(strict_types=1);
require_once __DIR__ . '/blog-functions.php';
function mg_blog_duplicate_post(PDO $pdo,int $postId,array $user,array &$errors): ?int { $post=mg_blog_get_admin_post($pdo,$postId); if(!$post){$errors[]='Source post was not found.'; return null;} $title=trim((string)$post['title']).' Copy'; $slug=mg_blog_unique_slug($pdo,(string)$post['slug'].'-copy'); $author=max(1,(int)($user['id']??0)); $s=$pdo->prepare('INSERT INTO blog_posts (title,slug,excerpt,body,featured_image,featured_image_alt,status,author_id,category_id,seo_title,seo_description,canonical_url,cta_type,is_featured,published_at,scheduled_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,NULL,NULL)'); $s->execute([$title,$slug,(string)($post['excerpt']??''),(string)($post['body']??''),$post['featured_image']??null,$post['featured_image_alt']??null,'draft',$author,!empty($post['category_id'])?(int)$post['category_id']:null,!empty($post['seo_title'])?(string)$post['seo_title'].' Copy':null,$post['seo_description']??null,null,(string)($post['cta_type']??'none'),0]); $newId=(int)$pdo->lastInsertId(); if($newId>0){$tags=mg_blog_tag_names($pdo,$postId); if($tags){mg_blog_sync_tags($pdo,$newId,implode(', ',$tags));} return $newId;} return null; }
